    driver.findElement(By.name("email")).sendKeys("bad-email");
    driver.findElement(By.name("phone")).sendKeys("123");
    driver.findElement(By.xpath("//button[contains(text(),'Book') or contains(text(),'Reserve')]")).click();
    wait.until(ExpectedConditions.visibilityOfElementLocated(By.cssSelector(".alert.alert-danger")));
